\label{def:multiamalgamation}
Let $L$ be a language, $\mathcal R$ be a Ramsey class of finite irreducible $L$-structures and $\mathcal U$ be a closure description (for $L$).
We say that a subclass $\mathcal K$ of $\mathcal R$  is an \emph{$(\mathcal R,\mathcal U)$-multiamalgamation class} if
the following conditions are satisfied:
\begin{enumerate}
 \item {\bf $\mathcal U$-closed structures:} $\mathcal K$ consists of finite $\mathcal U$-closed $L$-structures.
 \item\label{cond:hereditary} {\bf Hereditary property for $\mathcal U$-closed substructures:} For every $\str{A}\in {\mathcal K}$ and for every $\mathcal U$-closed substructure $\str{B}$ of $\str{A}$ we have $\str{B}\in {\mathcal K}$.
 \item\label{cond:amalgamation} {\bf Strong amalgamation property:}
For $\str{A},\str{B}_1,\str{B}_2\in {\mathcal K}$ and embeddings $\alpha_1\colon\str{A}\to\str{B}_1$, $\alpha_2\colon\str{A}\to\str{B}_2$, there is $\str{C}\in {\mathcal K}$ which is a strong amalgamation of $\str{B}_1$ and $\str{B}_2$ over $\str{A}$ with respect to $\alpha_1$ and $\alpha_2$.
 \item\label{cond:completion} {\bf Locally finite completion property:} Let $\str{B}\in {\mathcal K}$ and $\str{C}_0\in \mathcal R$. 
Then there exists $n=n(\str{B},\str{C}_0)$ such that if a $\mathcal U$-closed $L$-structure $\str{C}$ satisfies the following:
\begin{enumerate}
 \item $\str{C}_0$ is a $\mathcal U$-completion of $\str{C}$, 
 \item every $\mathcal U$-irreducible substructure of $\str{C}$ is in $\mathcal K$, and
 \item every (not necessarily $\mathcal U$-closed) substructure of $\str{C}$ with at most $n$ vertices has a $({\mathcal K},\mathcal U)$-completion,
\end{enumerate}
then there exists $\str{C}'\in {\mathcal K}$ which is a completion of $\str{C}$ with respect to copies of $\str{B}$.
\end{enumerate}

\label{prop:closures}
For every language $L=L_\mathcal R \cup L_\mathcal F$ there is a relational language $L'\supseteq L_\mathcal R$ and a closure
description $\mathcal U$ for $L'$ such that there is function $\mathop{\mathrm{Rel}}\nolimits$ assigning to every $L$-structure $\str{A}$ an $L'$-structure $\mathop{\mathrm{Rel}}\nolimits(\str{A})$
on the same vertex set satisfying the following:
\begin{enumerate}
\item $\mathop{\mathrm{Rel}}\nolimits$ is a bijection between $L$-structures and $\mathcal U$-closed $L'$-structures,
\item $\rel{A}{}=\nbrel{\mathop{\mathrm{Rel}}\nolimits(\str{A})}{}$ for every $R\in L_\mathcal R$,
\item $f\colon A\to B$ is a homomorphism-embedding from an $L$-structure $\str{A}$ to an $L$-structure $\str{B}$ if and only if it is an $\mathcal U$-homomorphism-embedding
from $\mathop{\mathrm{Rel}}\nolimits(\str{A})$ to $\mathop{\mathrm{Rel}}\nolimits(\str{B})$.
\end{enumerate}

\label{lem:usubstructure}
\label{lem:uclosedamalgamation}
For every language $L$ and a closure description $\mathcal U$ in $L$
the following holds:
\begin{enumerate}
\item Let $\str{A}$ be a substructure of a $\mathcal U$-closed $L$-structure $\str{B}$. Then
$\str{A}$ is a $\mathcal U$-substructure of $\str B$ if and only if $\str{A}$ is $\mathcal U$-closed.
\item\label{item:uclosedamalgamation} Let $\str{B}_1$ and $\str{B}_2$ be $\mathcal U$-closed $L$-structures
and $\str{A}$ a $\mathcal U$-closed substructure of both $\str{B}_1$ and $\str{B}_2$.
Further assume that completions in both cases are strong completions.
Then the free amalgamation of $\str{B}_1$ and $\str{B}_2$ over $\str{A}$ is a $\mathcal U$-closed structure.
\end{enumerate}

Let $L$ be a language and $\str{A}$ be an $L$-structure. Assume that $A = \{1, 2,\ldots, a\}$.  An \emph{$\str{A}$-partite $L$-system} is a tuple $(\str{A},{\mathcal X}_\str{B},\allowbreak \str{B})$ 
where $\str{B}$ is an $L$-struc\-ture and $\mathcal X_\str{B}=\{X^1_\str{B},X^2_\str{B},\ldots, X^a_\str{B}\}$  is a partition of the vertex set of $\str{B}$ into $a$ classes ($X^i_\str{B}$  are called \emph{parts} of $\str{B}$)  such that 
\begin{enumerate}
\item the mapping $\pi$ such that $\pi$ maps every $x \in X^i_\str{B}$ to $i$, $i = 1,2,\ldots,a$, is a
homo{\-}morphism-embedding $\str{B}\to\str{A}$ (we call $\pi$ the \emph{projection}); 
\item every tuple in every relation of $\str{B}$ contains at most one element of each class $X^i_\str{B}$ (these tuples are called \emph{transversal} with respect to the partition).
\end{enumerate}
\begin{remark}
Our definition differs from the definition used in~\cite{Nevsetvril1989}. We do not treat the linear order separately
and we also assume the existence of a homomorphism-embedding $\str{B}\to \str{A}$ (which simplifies the proof of the partite lemma). (This formulation of the partite system does not lead directly to a proof of the Ne\v set\v ril--R\"odl Theorem~\ref{thm:NR} itself. We aim for simplicity here.)
\end{remark}

