\label{prop:sep}
Let $R$ be a cut in an $L$-structure $\str{A}$ with components $A_1\neq A_2$.
Then $R$ is a minimal separating cut for $A_1$ and $A_2$ if and only if it is an inclusion minimal cut of $\str{A}$ separating $A_1$ and $A_2$.

\label{def:regular}
A family of finite structures ${\mathcal F}$ is  \emph{regular} if for every $n\geq 1$ the equivalence $\sim_{\mathcal F}$ has only
finitely many equivalence classes of width $n$.

\label{defn:weakorder}
Let $L$ be a language containing a binary relation $\leq$.
An $L$-structure $\str{F}$ is \emph{weakly ordered} if 
\begin{enumerate}
\item $\leq_\str{F}$ can be completed to linear order (in other words, it forms a reflexive acyclic digraph), and
\item for every pair of distinct vertices $a, b\in F$, either $(a,b)\in \leq_\str{F}$ or $(b,a)\in \leq_\str{F}$
if and only if $a,b$ is contained in an irreducible substructure of $\str{F}^-$ where $\str{F}^-$ is a shadow of $\str{F}$
in the language $L^-=L\setminus \{\leq\}$.
\end{enumerate}
(In other words, $\leq_\str{F}$ is an acyclic orientation of the Gaifman graph of the shadow of $\str{F}$ removing the relation $\leq_\str{F}$.)

\label{cor:forbH}
Let $L$ be a relational language and let ${\mathcal F}$ be a finite family of finite connected $L$-structures.
Then the class $\mathop{\mathrm{Age}}\nolimits(\mathop{\mathrm{Forb_{he}}}\nolimits({\mathcal F}))$ has a precompact Ramsey lift with the lift property.

