\label{doplnek}
Let $L$ be a language.
For every class of finite connected $L$-structures ${\mathcal F}$ it holds that ${\mathcal F}$ is regular if and only if $\overline{{\mathcal F}}$ is regular.

\label{cor:digraphs}
The class $\ordclass{\mathcal {D}}$ of all finite directed graphs with a free ordering of vertices is a Ramsey class.
The class $\ordclass{\mathcal {G}}$ of all finite (simple) graphs with a free ordering of vertices is a Ramsey class.

\label{prop:admisible}
Let $L$ be a language and ${\mathcal K}$, be a class of $L$-structures, and $\leq_L$ be a linear order of $\mathcal O_L$. If the lift $\ordclass {\mathcal K}$ of ${\mathcal K}$ adding a free order on vertices is
a Ramsey class then the lift $\ordclasssup {\mathcal K}{0}$ of ${\mathcal K}$ adding an $\leq_L$-admissible order on vertices is also a Ramsey class.

\label{cor:duals}
Let ${\mathcal F}$ be a regular family of finite connected weakly ordered structures such that all minimal separating cuts consist of one vertex.
Then there exists a Ramsey lift of $\mathop{\mathrm{Forb_h}}\nolimits({\mathcal F})$ adding only finitely many unary relations.

\label{defn:smetric}
Given $S\subseteq \mathbb R_{>0}$ (that is, a subset of positive reals) an \emph{$S$-metric
space $\str{A}$} is a pair $(A,d_\str{A})$ where $A$ is the vertex set and $d$ is
a binary function $d_\str{A}\colon A^2\to S\cup \{0\}$ (the \emph{distance function}) such that:
\begin{enumerate}
 \item $d_\str{A}(u,v)=0$ if and only if $u=v$,
 \item $d_\str{A}(u,v)=d_\str{A}(v,u)$, and
 \item $d_\str{A}(u,w)\leq d_\str{A}(u,v)+d_\str{A}(v,w)$ for every $w\in A$ (the \emph{triangle inequality}).
\end{enumerate}
We denote by $\mathcal M_S$ the class of all finite $S$-metric spaces.

\label{prop:sauer1}
Assume that $S\subseteq \mathbb R_{>0}$ is a subset of positive reals on which the $\oplus_S$ operation is defined and associative.
Then the following holds.
\begin{enumerate}
\item \label{cor:suaer1:1} Let $\str{G}$ be a finite $S$-metric graph.
Denote by $d'(u,v)$ the minimal $S$-length of a walk from $u$ to $v$ and by
$\vv{W}(u,v)$ the corresponding walk.
Then $\str{G}$ can be completed to an $S$-metric space $\str{A}$ by putting $d_\str{A}(u,v)=d'(u,v)$ for every pair $u\neq v\in G$.
\item \label{cor:suaer1:2} A finite $S$-graph $\str{G}$ is an $S$-metric graph if and only if all of its cycles are $S$-metric.
\end{enumerate}

\label{defn:jump}
Given $S\subseteq \mathbb R_{>0}$ and $a\in S$, we say that $a$ is a \emph{jump
number} if $a$ is not the maximum element of $S$ and there is no $b\in S$ with $a < b \leq 2a$.

\label{lem:archimedean}
Let $S\subseteq \mathbb R_{>0}$ be a set which has no jump numbers such that $\oplus_S$ is well-defined and associative. Then for every $a, b\in S$ there is an integer $n$ such that $n\times a \geq b$, where $n\times a$ is defined as
$$\underbrace{a\oplus a\oplus \cdots \oplus a}_{n\text{ times}}.$$

\label{lem:nonSmetric}
Let $S\subseteq \mathbb R_{>0}$ be a set which has no jump numbers such that $\oplus_S$ is well-defined and associative. Then for every finite $S'\subseteq S$ there is $n=n(S')$ such that every non-$S$-metric cycle which only uses distances from $S'$
has at most $n$ vertices.

