\label{thm:Smetric}
Let $S$ be a set of positive reals such that $S\cup\{0\}$ is closed. Then the following conditions are equivalent:
\begin{enumerate}
 \item\label{Smetric1} $S$ satisfies the 4-values condition,
 \item\label{Smetric2} $\mathcal M_S$ has the strong amalgamation property,
 \item\label{Smetric3} $\mathcal M_S$ has the amalgamation property, and
 \item\label{Smetric4} the class $\ordclasssup{\mathcal M}{S}$ of all convexly ordered $S$-metric spaces is Ramsey.
\end{enumerate}

\label{cor:Smetricfin}
Let $S$ be a set of positive reals such that $S\cup\{0\}$ is closed. Then the following conditions are equivalent:
\begin{enumerate}
 \item The class $\ordclasssup{\mathcal M}{S}$ of all convexly ordered $S$-metric spaces is Ramsey.
 \item There exists a Urysohn $S$-metric space.
\end{enumerate}

\label{thm:TO}
\label{thm:fatorder}
$\mathop{\mathrm{TO}}\nolimits(L)$ is a Ramsey class for every finite relational language $L$.

\label{thm:kcycle}
The class ${\mathcal K}_{\str C_l}$ is a Ramsey class. Every lift $\str{A}\in {\mathcal K}_{\str C_l}$ can be viewed as a metric space with distances truncated by $l+1\over 2$. 
More precisely, the following function $d_{\str{A}}\colon A\times A\to \{0,1,2,\ldots {l+1\over 2}\}$ is a metric:
$$d_{\str{A}}(u,v)=
\begin{cases}
0&\hbox{ if }u=v,\\
1&\hbox{ if }(u,v)\in E_{\str{A}},\\
d&\hbox{ if }(u,v)\in \nbrel{\str{A}}{d}, 2\leq d\leq {l-1\over 2}, and\\
{(l+1)\over 2}&\hbox{ otherwise.}
\end{cases}$$

\label{lem:lemma5}
Let $L$ be a relational language,
let $\mathcal M$ be a finite collection of finite $L$-structures, let $\str{U}$ be
an $\omega$-categorical existentially complete universal structure in $\mathop{\mathrm{Forb_m}}\nolimits(\mathcal M)$ and
let $\str{A}$ be a finite substructure of $\str{U}$. Then the following are equivalent:
\begin{enumerate}
\item $\str{A}$ is not algebraically closed in $\str{U}$.
\item There is $\str{M}\in \mathcal M$ and a substructure $\str{M}'$ of $\str{U}$ containing $\str{A}$ such that the following hold:
\begin{enumerate}
\item $\str M$ has a homomorphism to $\str M'$, and
\item there is a structure $\str S$ which can be obtained by a series of free amalgamations of $\vert M\vert$ copies of $\str M'$ over $\str A$ such that $\str M$ has a monomorphism to $\str S$.
\end{enumerate}
\end{enumerate}

\label{thm:CSSramsey}
Let $\mathcal M$ be a set of finite connected structures in a relational language $L$ such that $\mathop{\mathrm{Forb_m}}\nolimits(\mathcal M)$
contains an existentially complete $\omega$-categorical universal structure $\str{U}$.
Further assume that for every $\str{M}\in \mathcal M$ at least one of the following conditions holds:
\begin{enumerate}
  \item There is no homomorphism-embedding from $\str{M}$ to $\str{U}$, or
  \item $\str{M}$ can be constructed from irreducible structures by a series of free amalgamations over irreducible substructures.
\end{enumerate}
Then the class of all finite algebraically closed substructures of $\str{U}$ has a precompact Ramsey lift.
(By the standard homogenisation argument it also follows that $\mathop{\mathrm{Age}}\nolimits(\mathop{\mathrm{Forb_m}}\nolimits(\mathcal M))$ has a precompact Ramsey lift.)
